  "8:62": {
    "body": "다음 제시된 전제가 모두 참일 때, 전제들을 통해 내린 결론으로 옳은 것은?\n\n<전제>\nㄱ. 카메라를 사면 삼각대를 산다.\nㄴ. 플래시를 사지 않으면 삼각대를 사지 않는다.\nㄷ. 삼각대를 사면 렌즈를 산다.\nㄹ. 렌즈를 사면 메모리카드를 산다."
  },
  "9:61": {
    "body": "다음 제시된 전제가 모두 참일 때, 전제들을 통해 내린 결론으로 옳은 것은?\n\n<전제>\nㄱ. 영국에 가지 않으면 독일에 가지 않는다.\nㄴ. 네덜란드에 가지 않으면 영국에 가지 않는다.\nㄷ. 스페인에 가지 않으면 프랑스에 가지 않는다.\nㄹ. 영국에 가면 프랑스에 간다."
  },
  "10:61": {
    "body": "다음 제시된 전제가 모두 참일 때, 전제들을 통해 내린 결론으로 옳은 것은?\n\n<전제>\nㄱ. 날씨가 좋으면 사진을 찍는다.\nㄴ. 음악을 듣지 않으면 산책을 하지 않는다.\nㄷ. 기분이 좋으면 산책을 한다.\nㄹ. 기분이 좋지 않으면 사진을 찍지 않는다."
  },
  "10:64": {
    "body": "다음 제시된 전제가 모두 참일 때, 전제들을 통해 내린 결론으로 옳은 것은?\n\n<전제>\nㄱ. 수업을 들으면 복습을 한다.\nㄴ. 시험 점수가 높으면 좋은 학점을 받는다.\nㄷ. 내용을 이해하지 못하면 복습을 하지 않는다.\nㄹ. 내용을 이해하면 암기를 잘한다.\nㅁ. 시험 점수가 높지 않으면 암기를 잘하지 못한다."
  },
